-- Minotaur Warleader: 'spawns ... from multiple minotaur spots' -- join the
-- minotaur spawn groups at 2% (guide: spawn-in-place-of).
INSERT IGNORE INTO `spawnentry` (`spawngroupID`,`npcID`,`chance`)
SELECT DISTINCT se.spawngroupID, 440716, 2 FROM spawnentry se
JOIN spawn2 s2 ON s2.spawngroupID = se.spawngroupID
WHERE s2.zone = 'gyrospireb' AND s2.version = 0
  AND se.npcID IN (440032,440036,440044,440054,440059,440066)
  AND NOT EXISTS (SELECT 1 FROM spawnentry x WHERE x.spawngroupID = se.spawngroupID AND x.npcID = 440716);

-- ---------------------------------------------------------------- instance-only trash drops
-- Guide: 'In instanced versions of the zone, but not the static version,'
-- 'mobs can rarely drop ...'. This server's mission dz instances are full
-- static copies (zone_version 0), so the split is not modelled: 1% on the
-- zone trash loottables (guard: NOT EXISTS). Documented simplification.

-- gyrospireb: item 101354
INSERT INTO `lootdrop_entries` (`lootdrop_id`,`item_id`,`item_charges`,`equip_item`,`chance`)
SELECT DISTINCT le.lootdrop_id, 101354, 1, 0, 1 FROM npc_types n
JOIN spawnentry se ON se.npcID = n.id
JOIN spawn2 s2 ON s2.spawngroupID = se.spawngroupID
JOIN loottable_entries le ON le.loottable_id = n.loottable_id
WHERE s2.zone = 'gyrospireb' AND s2.version = 0 AND n.id BETWEEN 440000 AND 440079
  AND n.loottable_id > 0
  AND NOT EXISTS (SELECT 1 FROM lootdrop_entries de WHERE de.lootdrop_id = le.lootdrop_id AND de.item_id = 101354);
